<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\DeviceSession; use App\Models\User; use App\Services\Audit\AuditLogger; use App\Services\Auth\DeviceSessionService; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\View\View;
class SessionController extends Controller { public function index(): View { return view('admin.sessions.index',['sessions'=>DeviceSession::with('user')->latest('last_seen_at')->paginate(50)]); } public function revoke(Request $r, DeviceSession $deviceSession, DeviceSessionService $s, AuditLogger $a): RedirectResponse { $s->revoke($deviceSession); $a->log('session.revoked',$deviceSession,null,['user_id'=>$deviceSession->user_id]); return back()->with('success','Device session revoked.'); } public function revokeAll(Request $r, User $user, DeviceSessionService $s, AuditLogger $a): RedirectResponse { $count=$s->revokeAll($user); $a->log('session.revoked_all',$user,null,['count'=>$count]); return back()->with('success',"{$count} active device session(s) revoked."); } }
